"""RoadSense experimental sensor profile recorder (Stages W9-W11), for worlds generated by tools/sensor_profile.py only.

A Robot nested in EGO_ROADSENSE's sensorsSlotCenter (its frame is the ego frame: origin at the rear axle, x forward,
y left, z up) carrying the profile's own sensors: copies of RoadSense's front and rear radars at the same mounts, four
corner radars, a 16-layer roof lidar, a 720p forward camera (recording only) and a GPS/IMU. It never touches the ego's
devices or the ego's controller (roadsense_ego), so RoadSense's own perception runs exactly as in the original world.

ROADSENSE_SENSOR_RECORD (a directory) switches recording on; unset, the controller only steps. Writes:
  records.jsonl  one line per radar instant: raw radar targets, GPS/IMU, the ego pose and, for scoring only, the pose
                 of every SUMO vehicle node (never an input to RoadSense perception)
  lidar.bin      raw float32 range images (row-major, layer 0 = top), offsets in records.jsonl
  camera_*.png   720p frames every ROADSENSE_PROFILE_CAMERA_S simulated seconds (0 = camera off)
Periods: ROADSENSE_PROFILE_RADAR_MS (100), ROADSENSE_PROFILE_LIDAR_MS (100; 0 = lidar off). Python 3.9, standard library only.
"""
import ctypes
import json
import math
import os

from controller import Supervisor
from controller.wb import wb

robot = Supervisor()
STEP = int(robot.getBasicTimeStep())
out_dir = os.environ.get("ROADSENSE_SENSOR_RECORD", "").strip()
if not out_dir:
    while robot.step(STEP * 100) != -1:
        pass
    raise SystemExit(0)

RADAR_MS = int(os.environ.get("ROADSENSE_PROFILE_RADAR_MS", "100"))
LIDAR_MS = int(os.environ.get("ROADSENSE_PROFILE_LIDAR_MS", "100"))
CAMERA_S = float(os.environ.get("ROADSENSE_PROFILE_CAMERA_S", "0"))
RANGE_M = 150.0  # ground truth: SUMO vehicles within this distance of the ego
RADARS = ["profile radar front", "profile radar rear", "profile radar corner fl", "profile radar corner fr",
          "profile radar corner rl", "profile radar corner rr"]

log = open(os.path.join(out_dir, "records.jsonl"), "x", buffering=1)
lidar_bin = open(os.path.join(out_dir, "lidar.bin"), "xb")
radars = {name: robot.getDevice(name) for name in RADARS}
for dev in radars.values():
    dev.enable(RADAR_MS)
lidar = robot.getDevice("profile lidar roof")
if LIDAR_MS > 0:
    lidar.enable(LIDAR_MS)
camera = robot.getDevice("profile camera 720p")
if CAMERA_S > 0:
    camera.enable(int(CAMERA_S * 1000))
gps, imu = robot.getDevice("profile gps"), robot.getDevice("profile imu")
gps.enable(STEP)
imu.enable(STEP)
ego = robot.getFromDef("WEBOTS_VEHICLE0")
sumo_nodes = []  # SUMO_VEHICLE<n> wrappers, imported by sumo_supervisor as traffic appears


def emit(**record):
    log.write(json.dumps(record, separators=(",", ":")) + "\n")


def pose(node):
    """World x, y, z, yaw, then the row-major rotation matrix."""
    p, m = node.getPosition(), node.getOrientation()
    return [round(p[0], 4), round(p[1], 4), round(p[2], 4), round(math.atan2(m[3], m[0]), 6)] + [round(v, 7) for v in m]


def refresh_nodes():
    while True:
        node = robot.getFromDef("SUMO_VEHICLE%d" % len(sumo_nodes))
        if node is None:
            return
        model = node.getField("children").getMFNode(0)
        sumo_nodes.append((node, model, node.getField("name"), model.getTypeName()))


def ground_truth(ego_pose):
    vehicles = []
    for i, (node, model, name, type_name) in enumerate(sumo_nodes):
        p = node.getPosition()
        if math.hypot(p[0] - ego_pose[0], p[1] - ego_pose[1]) > RANGE_M:
            continue
        v = node.getVelocity()
        vehicles.append({"node": i, "id": name.getSFString(), "model_type": type_name, "wrapper": pose(node),
                         "model": pose(model), "v": [round(c, 4) for c in v[:2]] + [round(v[5], 5)]})
    return vehicles


emit(type="start", basic_time_step=STEP, radar_ms=RADAR_MS, lidar_ms=LIDAR_MS, camera_s=CAMERA_S,
     radars={name: {"max_range": d.getMaxRange(), "hfov": d.getHorizontalFov(), "vfov": d.getVerticalFov()}
             for name, d in radars.items()},
     lidar={"w": lidar.getHorizontalResolution(), "layers": lidar.getNumberOfLayers(), "fov": lidar.getFov(),
            "vfov": lidar.getVerticalFov(), "min_range": lidar.getMinRange(), "max_range": lidar.getMaxRange()})
k = 0
while robot.step(STEP) != -1:
    k += 1
    ms = k * STEP
    radar_now, lidar_now = ms % RADAR_MS == 0, LIDAR_MS > 0 and ms % LIDAR_MS == 0
    camera_now = CAMERA_S > 0 and ms % int(CAMERA_S * 1000) == 0
    if not (radar_now or lidar_now or camera_now):
        continue
    if ms % 1000 == 0 or not sumo_nodes:
        refresh_nodes()
    ego_pose = pose(ego)
    rec = {"type": "sample", "t": round(robot.getTime(), 3), "ego": ego_pose,
           "ego_v": [round(c, 4) for c in ego.getVelocity()[:2]] + [round(ego.getVelocity()[5], 5)],
           "gps": [round(v, 4) for v in gps.getValues()], "gps_speed": round(gps.getSpeed(), 4),
           "imu_rpy": [round(v, 6) for v in imu.getRollPitchYaw()], "gt": ground_truth(ego_pose)}
    if radar_now:
        rec["radars"] = {name: [[round(t.distance, 4), round(t.azimuth, 6), round(t.speed, 4),
                                 round(t.receiver_power, 2)] for t in dev.getTargets()]
                         for name, dev in radars.items()}
    if lidar_now:
        n = lidar.getHorizontalResolution() * lidar.getNumberOfLayers()
        offset = lidar_bin.tell()
        lidar_bin.write(ctypes.string_at(wb.wb_lidar_get_range_image(lidar._tag), n * 4))
        rec["lidar"] = {"offset": offset, "n": n}
    if camera_now:
        path = "camera_%07d.png" % ms
        camera.saveImage(os.path.join(out_dir, path), 90)
        rec["camera"] = path
    emit(**rec)
